import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.*;
import java.util.stream.*;

public class Main {

    public void solve(InputReader inp) throws IOException {
        List<Integer> nk = inp.readlnInts();
        int n = nk.get(0);
        int k = nk.get(1);
        List<Integer> aList = inp.readlnInts();
        int[] a = new int[aList.size()];
        for (int i = 0; i < aList.size(); i++) {
            a[i] = aList.get(i);
        }
        int lim = a[k - 1];
        int ans = 0;
        for (int it : a) {
            if (it > 0 && it >= lim) {
                ans++;
            }
        }
        System.out.print(ans);
    }

    public static class InputReader {
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        public String readln() throws IOException {
            return br.readLine();
        }

        public int readlnInt() throws IOException {
            return Integer.parseInt(readln());
        }

        public long readlnLong() throws IOException {
            return Long.parseLong(readln());
        }

        public double readlnDouble() throws IOException {
            return Double.parseDouble(readln());
        }

        public List<String> readlnStrings() throws IOException {
            return Arrays.asList(readln().split(" ", -1));
        }

        public List<Integer> readlnInts() throws IOException {
            return readlnStrings().stream().map(Integer::parseInt).collect(Collectors.toList());
        }

        public List<Long> readlnLongs() throws IOException {
            return readlnStrings().stream().map(Long::parseLong).collect(Collectors.toList());
        }

        public List<Double> readlnDoubles() throws IOException {
            return readlnStrings().stream().map(Double::parseDouble).collect(Collectors.toList());
        }
    }

    public static void main(String[] args) throws IOException {
        new Main().solve(new InputReader());
    }
}
